import{_ as a,c as e,o as s,a3 as i}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Tracking stock","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/tracking/index.md","filePath":"master/supply-chain/inventories/tracking/index.md","lastUpdated":1791902625000}'),o={name:"master/supply-chain/inventories/tracking/index.md"};function r(n,t,l,c,d,h){return s(),e("div",null,t[0]||(t[0]=[i(`<h1 id="tracking-stock" tabindex="-1">Tracking stock <a class="header-anchor" href="#tracking-stock" aria-label="Permalink to &quot;Tracking stock&quot;">​</a></h1><p>Tracking answers the question &quot;which exact goods are these?&quot;. Without tracking, Aureus knows you hold 100 tablets. With tracking, it knows which batch they came from or which box they sit in. This group covers lots, serial numbers and packages.</p><blockquote><p><strong>In simple words:</strong> A lot labels a batch, a serial number labels one item, and a package is a physical box.</p></blockquote><h2 id="pick-the-right-tool" tabindex="-1">Pick the right tool <a class="header-anchor" href="#pick-the-right-tool" aria-label="Permalink to &quot;Pick the right tool&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it labels</th><th>Good for</th></tr></thead><tbody><tr><td>Lot</td><td>A batch of identical units</td><td>Medicine, food, chemicals</td></tr><tr><td>Serial number</td><td>One single unit</td><td>Laptops, machines, devices</td></tr><tr><td>Package</td><td>A box, pallet or parcel that holds products</td><td>Shipping and storing</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Product  →  Lot MC-VITC-001 (250 tablets)</span></span>
<span class="line"><span>Product  →  Serial SN-00045 (1 unit)</span></span>
<span class="line"><span>Box PACK007  →  holds several products</span></span></code></pre></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Each tool has its own switch in <code>Inventory → Settings</code>.</p><ul><li><strong>Lots &amp; Serial Numbers</strong> on <strong>Manage Traceability</strong>.</li><li><strong>Packages</strong> on <strong>Manage Operations</strong>.</li></ul><p>See <a href="./../get-started/inventory-settings.html">Inventory settings</a>.</p><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What you learn</th></tr></thead><tbody><tr><td><a href="./lots-and-serial-numbers.html">Lots and serial numbers</a></td><td>Turn on tracking, assign numbers on receipts and deliveries</td></tr><tr><td><a href="./packages.html">Packages</a></td><td>Package types, package records, destination package</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Decide on tracking before stock arrives. Adding it later to a product that already has stock needs a recount.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../products/configure-product.html">Configure a product</a></li><li><a href="./../operations/receipts.html">Receipts</a></li><li><a href="./../operations/deliveries.html">Deliveries</a></li></ul>`,15)]))}const u=a(o,[["render",r]]);export{g as __pageData,u as default};
